const $=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const data={get(k){try{return localStorage.getItem('fondasi-pecahan-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-pecahan-'+k,v);return true}catch{return false}}};
function bar(target,n,d){target.replaceChildren();for(let i=0;i<d;i++){const piece=document.createElement('span');piece.className='piece'+(i<n?' filled':'');piece.setAttribute('aria-hidden','true');target.append(piece)}}
function fraction(){const d=Number($('#den').value);$('#num').max=d*2;if(Number($('#num').value)>d*2)$('#num').value=d*2;const n=Number($('#num').value);$('#num-out').value=n;$('#den-out').value=d;$('#fraction-display').textContent=`${n}/${d}`;$('#bars').replaceChildren();for(let row=0;row<2;row++){const b=document.createElement('div');b.className='single-bar';bar(b,Math.max(0,Math.min(d,n-row*d)),d);$('#bars').append(b)}$('#bars').setAttribute('aria-label',`${n} bagian berukuran satu per ${d}, dari dua batang yang masing-masing mewakili satu utuh.`);$('#ticks').replaceChildren();for(let i=0;i<=d*2;i++){const x=30+270*i/d,line=document.createElementNS(ns,'line');for(const [k,v] of Object.entries({x1:x,x2:x,y1:58,y2:72,stroke:'#244d40'}))line.setAttribute(k,v);$('#ticks').append(line);if(i===0||i===d||i===2*d){const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',108);t.setAttribute('text-anchor','middle');t.textContent=i/d;$('#ticks').append(t)}}const x=30+270*n/d;$('#dot').setAttribute('cx',x);$('#dot-label').setAttribute('x',Math.max(55,Math.min(545,x)));$('#dot-label').textContent=`${n}/${d}`;$('#fraction-feedback').textContent=`${n}/${d} berarti ${n} bagian yang masing-masing berukuran 1/${d}. `+(n===0?'Tidak ada bagian berwarna. Nilainya 0.':n<d?'Nilainya di antara 0 dan 1.':n===d?'Satu batang terisi penuh. Nilainya tepat 1.':n===2*d?'Dua batang terisi penuh. Nilainya tepat 2.':`Satu utuh terisi, ditambah ${n-d}/${d} dari batang berikutnya. Nilainya lebih dari 1 dan kurang dari 2.`)}$('#num').addEventListener('input',fraction);$('#den').addEventListener('input',fraction);$('#reset').addEventListener('click',()=>{$('#den').value=4;$('#num').max=8;$('#num').value=3;fraction()});fraction();
function equivalent(){const k=Number($('#factor').value);$('#factor-out').value=k;bar($('#equivalent-base'),1,2);bar($('#equivalent-new'),k,k*2);$('#equivalent-new').setAttribute('aria-label',`${k} per ${k*2}, dengan panjang bagian berwarna sama dengan setengah batang`);$('#equivalent-feedback').textContent=`1/2 = (1 × ${k})/(2 × ${k}) = ${k}/${2*k}. Bagian berwarna tetap setengah batang; sekarang kita menghitung ${k} potongan yang lebih kecil.`}$('#factor').addEventListener('input',equivalent);equivalent();
const pairs=[{a:[1,4],b:[1,8],why:'1/4 > 1/8. Untuk satu utuh yang sama, satu bagian seperempat lebih besar daripada satu bagian seperdelapan.'},{a:[3,4],b:[1,2],why:'3/4 > 1/2. Karena 1/2 = 2/4, kita membandingkan 3 bagian dengan 2 bagian yang sama-sama berukuran seperempat.'},{a:[2,3],b:[3,4],why:'2/3 < 3/4. Karena 2/3 = 8/12 dan 3/4 = 9/12, delapan bagian seperdua belas lebih sedikit daripada sembilan bagian.'},{a:[1,2],b:[2,4],why:'1/2 = 2/4. Dua batang memiliki bagian berwarna yang sama panjang. Keduanya adalah pecahan senilai.'}];function compare(){const p=pairs[Number($('#comparison').value)];for(const side of ['a','b']){const [n,d]=p[side];bar($('#compare-'+side),n,d);$('#compare-'+side).setAttribute('aria-label',`${n} per ${d}, satu utuh berukuran sama dengan batang pembanding`);$('#compare-'+side+'-label').textContent=`${n}/${d}`}$('#comparison-feedback').textContent=p.why}$('#comparison').addEventListener('change',compare);compare();
$('#check').addEventListener('click',()=>{const v=document.querySelector('[name=check]:checked')?.value;$('#check-feedback').textContent=!v?'Pilih satu dugaan dahulu. Tidak apa-apa jika belum yakin.':v==='quarter'?'Tepat. Satu utuh yang sama dibagi menjadi lebih sedikit bagian, sehingga setiap bagian lebih besar.':'Perhatikan ukuran setiap bagian. Dari satu utuh yang sama, seperempat lebih besar daripada seperdelapan. Coba kedua pecahan pada lab mini di bawah.'});
const qs=[{text:'Satu batang dibagi menjadi 5 bagian sama besar. Tiga bagian diwarnai. Berapa pembilang pecahannya?',a:3,h:'Pembilang menghitung banyak bagian yang diambil atau diwarnai.',why:'Pembilangnya 3. Pecahan bagian berwarna adalah 3/5.'},{text:'Lengkapi pecahan senilai: 2/3 = □/12. Berapa isi kotak?',a:8,h:'Penyebut 3 dikalikan berapa agar menjadi 12? Kalikan pembilang dengan faktor yang sama.',why:'Karena 3 × 4 = 12, pembilang juga dikalikan 4. Jadi 2/3 = 8/12.'},{text:'Dari 1/4 dan 1/8, pecahan yang lebih besar memiliki penyebut berapa?',a:4,h:'Bayangkan satu batang dibagi menjadi 4 atau 8 bagian. Bandingkan ukuran satu bagiannya.',why:'Penyebutnya 4. Pada satu utuh yang sama, satu bagian seperempat lebih besar daripada satu bagian seperdelapan.'},{text:'Berapa banyak bagian seperempat yang membentuk tepat satu utuh?',a:4,h:'Satu utuh dibagi menjadi empat bagian sama besar.',why:'Diperlukan 4 bagian. Jadi 4/4 = 1.'},{text:'Untuk 5/4, setelah satu utuh terisi, berapa bagian seperempat yang masih tersisa?',a:1,h:'Satu utuh memuat 4 bagian seperempat. Bandingkan dengan 5 bagian.',why:'Tersisa 1 bagian seperempat. Jadi 5/4 adalah satu utuh ditambah 1/4.'}];const solved=new Set();$('#questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.text}</p><form class="number-form" data-q="${i}"><label for="answer${i}">Jawaban latihan ${i+1}</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="numeric" required autocomplete="off" aria-describedby="feedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="feedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.h}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const i=Number(f.dataset.q),s=$('#answer'+i).value.trim(),ok=/^\d+$/.test(s)&&Number(s)===qs[i].a;$('#feedback'+i).className='feedback '+(ok?'correct':'incorrect');$('#feedback'+i).textContent=ok?'Tepat. '+qs[i].why:'Belum tepat. Tulis satu bilangan dan gunakan petunjuk untuk memeriksa alasanmu.';if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari ${qs.length} latihan telah dijawab dengan tepat.`}));$('#reflection').value=data.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#reflection-note').textContent=data.set('reflection',$('#reflection').value)?'Catatan tersimpan pada peramban ini.':'Catatan belum bisa disimpan. Salin tulisanmu jika ingin menyimpannya.'});function completed(){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓'}if(data.get('complete')==='yes')completed();$('#complete').addEventListener('click',()=>{const ok=data.set('complete','yes');completed();$('#complete-note').textContent=ok?'Kemajuan tersimpan pada peramban ini. Kamu bisa kembali berlatih kapan saja.':'Selesai. Kemajuan belum dapat disimpan pada peramban ini.'});
